import vuedraggable from 'vuedraggable'
import uploadPictures from '@/components/uploadPictures';
export default {
    name: 'c_tab_bar',
    props: {
        name: {
            type: String
        },
        configData:{
            type:null
        }
    },
    components: {
        uploadPictures,
        draggable: vuedraggable
    },
    data () {
        return {
            modalPic: false,
            isChoice: '单选',
            gridBtn: {
                xl: 4,
                lg: 8,
                md: 8,
                sm: 8,
                xs: 8
            },
            gridPic: {
                xl: 6,
                lg: 8,
                md: 12,
                sm: 12,
                xs: 12
            },
            activeIndex: 0,
            isSelect:0,
            datas: this.configData,
            lastObj:{}
        }
    },
    mounted () {},
    watch: {
        configData: {
            handler (nVal, oVal) {
                this.datas = nVal
            },
            deep: true
        },
    },
    methods: {
        // 添加模块
        addMenu(){
            if (this.configData[this.name].list.length == 0) {
                this.configData[this.name].list.push(this.lastObj)
            } else {
                let obj = JSON.parse(JSON.stringify(this.configData[this.name].list[this.configData[this.name].list.length - 1]));
                this.configData[this.name].list.push(obj)
            }
        },
        deleteMenu(index){
            this.$Modal.confirm({
                title: '提示',
                content: '是否确定删除该菜单',
                onOk: () => {
                    if (this.configData[this.name].list.length == 1) {
                        this.lastObj = this.configData[this.name].list[0]
                    }
                    this.configData[this.name].list.splice(index,1)
                },
                onCancel: () => {
                }
            });

        },
        // 点击图文封面
        modalPicTap(title, index, select) {
            this.activeIndex = index;
            this.modalPic = true;
            this.isSelect = select;
        },
        // 获取图片信息
        getPic(pc) {
            this.$nextTick(() => {
                this.configData[this.name].list[this.activeIndex].imgList[this.isSelect] = pc.att_dir;
                this.modalPic = false;
            })
        }
    }
}
